      function CG$SuppressFrame (num_recs in Number) return boolean is
-- TEMPLATE DERIVED CODE
begin
  return(num_recs > 0);
end;

      FUNCTION GET_PORT_NAME RETURN char IS
	V_PORT_NAME		VARCHAR2(100);
BEGIN
	TOOL_ENV.GETVAR('PORT_NAME',V_PORT_NAME);
	RETURN V_PORT_NAME;
END;

      function C_LIC_TYPEFormula return Char is
V_DESC VARCHAR2(200);
begin
  SELECT RV_MEANING
  INTO   V_DESC
  FROM   CG_REF_CODES 
  WHERE  RV_LOW_VALUE  = TO_CHAR(:LIC_TYPE)
  AND    RV_DOMAIN  LIKE 'LICENSE TYPE' ;

  RETURN (V_DESC);
  EXCEPTION
  WHEN OTHERS THEN
  RETURN NULL;
end;

      function V_HEDFormula return Char is
begin
  		RETURN ('تقرير بالمخلصين العموميين والمناديب والمعقبين  ');
end;

      function F_LIC_TYPEFormatTrigger return boolean is
begin

  -- مولد تلقائياً من باني التقرير.
  if (:P_WORK_PORT_TYPE IS NOT NULL)
  then
    return (FALSE);
  end if;

  return (TRUE);
end;

      function PORT_NAMEFormula return Char is
P_PORT_NAME  VARCHAR2(200);
begin
  SELECT  PORT_NAME
	INTO    P_PORT_NAME
	FROM    SD_PORTS
	WHERE   PORT_CD = :P_CURR_PORT_CD ;
  RETURN (P_PORT_NAME);
EXCEPTION
	WHEN NO_DATA_FOUND THEN
	RETURN(NULL);
		WHEN OTHERS THEN
	RETURN(NULL);
end;

